INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c20d1e17-3623-4448-99a6-1c8146565526', 'b2b2b2b2-3030-4000-8000-000000000002', 23, 'Dia 23 — Identidade restaurada', 'Semana 4: Integrar', '{"pch": "Eu te chamei pelo teu nome, tu \u00e9s meu\u2026 Sua identidade n\u00e3o est\u00e1 na dor \u2014 est\u00e1 em quem te criou.", "verse": "Is 43,1", "lectio": "Leia Is 43,1-7. Precioso aos olhos de Deus.", "practice": "Escreva: Eu sou mais do que aconteceu comigo porque _____", "question": "Como voc\u00ea se define al\u00e9m da sua dor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;